/* QUICK TOOLS — xử lý ngay trong trình duyệt, không upload ảnh lên server. */
let toolTab='colour',pickedImage=null,pickedHex='',pickedRgb='',pickedAlpha=255,copyFormat='hex',imageName='';
let unitState={width:'5',height:'3',unit:'m',dpi:'72'};
let timerRemaining=5*60*1000,timerDeadline=0,timerRunning=false,timerMinutes='5',timerInterval=0;
function colourPanel(){return '<div id="dropzone" class="dropzone"><p>'+t('drop')+'</p><button class="btn" id="choose-image">'+t('chooseImage')+'</button><input type="file" id="image-file" accept="image/png,image/jpeg,image/webp,image/gif" hidden><small>PNG · JPG · WebP · GIF / 25 MB</small><small>'+t('uploadNote')+'</small></div><div class="row space" style="margin-top:14px"><small class="tool-meta">'+t('copyAs')+'</small><div class="row"><button class="filter-chip" data-copy-format="hex" aria-pressed="'+(copyFormat==='hex')+'">HEX</button><button class="filter-chip" data-copy-format="rgb" aria-pressed="'+(copyFormat==='rgb')+'">RGB</button></div></div><p class="tool-meta" style="margin-top:12px">'+t('pickHint')+'</p><div id="image-stage" class="image-stage" '+(pickedImage?'':'hidden')+'><canvas id="picker-canvas" tabindex="0" aria-label="'+t('colourTool')+'"></canvas></div><div id="colour-result"></div><div class="tool-meta" id="image-meta">'+esc(imageName)+'</div><p class="tool-error" id="image-error" role="status"></p>'}
function wireColour(){const zone=$('#dropzone'),input=$('#image-file');$('#choose-image').onclick=()=>input.click();input.onchange=()=>{if(input.files[0])loadImage(input.files[0])};['dragenter','dragover'].forEach(type=>zone.addEventListener(type,e=>{e.preventDefault();zone.classList.add('dragover')}));['dragleave','drop'].forEach(type=>zone.addEventListener(type,e=>{e.preventDefault();zone.classList.remove('dragover')}));zone.addEventListener('drop',e=>{const f=e.dataTransfer.files[0];if(f)loadImage(f)});$('#picker-canvas').onclick=e=>{const canvas=e.currentTarget,r=canvas.getBoundingClientRect();samplePixel(Math.min(canvas.width-1,Math.max(0,Math.floor((e.clientX-r.left)*canvas.width/r.width))),Math.min(canvas.height-1,Math.max(0,Math.floor((e.clientY-r.top)*canvas.height/r.height))))};$('#picker-canvas').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();const c=e.currentTarget;samplePixel(Math.floor(c.width/2),Math.floor(c.height/2))}};showColour()}
let imageLoadVersion=0;
function loadImage(file){const version=++imageLoadVersion;if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>25*1024*1024){$('#image-error').textContent=t('badImage');return}const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{URL.revokeObjectURL(url);if(version!==imageLoadVersion)return;if(im.naturalWidth*im.naturalHeight>36000000||!im.naturalWidth){if($('#image-error'))$('#image-error').textContent=t('badImage');return}pickedImage=im;imageName=file.name+' · '+im.naturalWidth+' × '+im.naturalHeight+' px';pickedHex='';pickedRgb='';if(toolTab==='colour'&&!!currentTool)renderTools()};im.onerror=()=>{URL.revokeObjectURL(url);if(version===imageLoadVersion&&$('#image-error'))$('#image-error').textContent=t('badImage')};im.src=url}
function drawImage(){const c=$('#picker-canvas');if(!c||!pickedImage)return;c.width=pickedImage.naturalWidth;c.height=pickedImage.naturalHeight;c.getContext('2d',{willReadFrequently:true}).drawImage(pickedImage,0,0);$('#image-stage').hidden=false;$('#image-meta').textContent=imageName}
function samplePixel(x,y){const c=$('#picker-canvas');if(!c||!pickedImage)return;const data=c.getContext('2d',{willReadFrequently:true}).getImageData(x,y,1,1).data;if(data[3]===0){toast(t('transparent'));return}pickedHex='#'+[...data].slice(0,3).map(x=>x.toString(16).padStart(2,'0')).join('').toUpperCase();pickedRgb='rgb('+[...data].slice(0,3).join(', ')+')';pickedAlpha=data[3];showColour();clipboard(copyFormat==='hex'?pickedHex:pickedRgb)}
function showColour(){if(!$('#colour-result'))return;$('#colour-result').innerHTML=pickedHex?'<div class="colour-result"><span class="colour-chip" style="background:'+pickedHex+'"></span>'+copy(pickedHex,pickedHex)+copy(pickedRgb,pickedRgb)+(pickedAlpha<255?'<small class="tool-meta">'+t('alpha')+': '+Math.round(pickedAlpha/255*100)+'%</small>':'')+'</div>':''}
const TOOL_IDS=['colour','qr','images','contrast','pdf'];
const TOOL_NAMES={colour:P('Lấy màu','Pick colours'),qr:P('Tạo QR','QR code'),images:P('Ảnh hàng loạt','Batch images'),contrast:P('Tương phản','Contrast'),pdf:P('Chỉnh trang PDF','PDF pages'),unit:P('Đổi đơn vị','Units'),timer:P('Đếm giờ','Timer')};
const B=(vi,en)=>lang==='vi'?vi:en;
const libs={};
async function loadToolLibrary(name){const configs={qr:['assets/qr-code-styling.min.js','QRCodeStyling'],pdf:['assets/pdf-lib.min.js','PDFLib'],zip:['assets/fflate.min.js','fflate']},cfg=configs[name];if(window[cfg[1]])return window[cfg[1]];if(!libs[name])libs[name]=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=cfg[0];script.onload=()=>window[cfg[1]]?resolve(window[cfg[1]]):reject(Error(B('Thư viện chưa sẵn sàng.','The library is not ready.')));script.onerror=()=>{delete libs[name];script.remove();reject(Error(B('Không tải được thư viện trong assets/.','Could not load the library from assets/.')))};document.head.append(script)});return libs[name]}
function safeFileName(name,fallback='UEL'){return (String(name||'').normalize('NFC').replace(/[\u0000-\u001f\u007f\u202a-\u202e<>:"/\\|?*]/g,'').trim().replace(/[. ]+$/,'').slice(0,100)||fallback)}
function stripExtension(name){return name.replace(/\.[^.]+$/,'')}
function saveToolBlob(blob,name){if(!blob||!blob.size)throw Error(B('File xuất đang trống.','The exported file is empty.'));const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
const nextPaint=()=>new Promise(resolve=>requestAnimationFrame(()=>setTimeout(resolve,0)));
const mb=n=>n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB';
function toolMessage(id,text,error=false){const node=$(id);if(node){node.textContent=text;node.classList.toggle('error',error)}}
function toolField(label,control){return '<label>'+esc(label)+control+'</label>'}
function toolInput(id,value,extra=''){return '<input id="'+id+'" value="'+esc(value)+'" '+extra+'>'}
function toolOptions(values,current){return values.map(([value,text])=>'<option value="'+esc(value)+'" '+(String(current)===String(value)?'selected':'')+'>'+esc(text)+'</option>').join('')}
function bindToolDrop(zone,input,callback){if(!zone||!input)return;input.onchange=()=>{const files=[...input.files];input.value='';callback(files)};['dragenter','dragover'].forEach(type=>zone.addEventListener(type,e=>{e.preventDefault();zone.classList.add('dragover')}));['drop','dragleave'].forEach(type=>zone.addEventListener(type,e=>{e.preventDefault();zone.classList.remove('dragover')}));zone.addEventListener('drop',e=>callback([...e.dataTransfer.files]))}
function uploader(id,accept,label,multiple,note){return '<div class="tool-drop" id="'+id+'-drop"><p>'+esc(label)+'</p><button class="btn" data-pick-input="'+id+'">'+B('Chọn file','Choose files')+'</button><input id="'+id+'" type="file" accept="'+accept+'" '+(multiple?'multiple':'')+' hidden><small>'+esc(note)+'</small><small>'+B('Xử lý file trực tiếp trên thiết bị.','Files stay on your device.')+'</small></div>'}
document.addEventListener('click',e=>{const pick=e.target.closest('[data-pick-input]');if(pick){const input=$('#'+pick.dataset.pickInput);if(input&&!pick.disabled)input.click()}});

/* QR: preset UEL, 4 mô-đun lề tối thiểu, tên và bộ đếm riêng theo trình duyệt. */
const qrState={data:'',dots:'#144e8c',corners:'#144e8c',centres:'#f05a22',background:'#ffffff',transparent:true,style:'rounded',cornerStyle:'extra-rounded',centreStyle:'extra-rounded',size:1024,format:'png',filename:'',busy:false,version:0,counter:0};
function qrNextNumber(){let count=qrState.counter;try{count=Math.max(count,Number(localStorage.getItem('meo-qr-download-count'))||0)}catch{}return count+1}
function qrPanel(){return '<div class="tool-grid"><div class="tool-fields">'+toolField(B('Link hoặc nội dung','Link or text'),'<textarea id="qr-data" maxlength="1000" placeholder="https://…">'+esc(qrState.data)+'</textarea>')+'<div class="row">'+btn('UEL','data-qr-preset="uel"')+btn(B('Trắng / nền tối','White / dark background'),'data-qr-preset="white"')+btn(B('Đen / trắng','Black / white'),'data-qr-preset="black"')+'</div><details class="tool-details"><summary>'+B('Màu sắc & nền','Colours & background')+'</summary><div class="tool-fields"><div class="tool-two">'+toolField(B('Màu chấm','Dot colour'),toolInput('qr-dots',qrState.dots,'type="color"'))+toolField(B('Viền góc','Corner outline'),toolInput('qr-corners',qrState.corners,'type="color"'))+toolField(B('Tâm góc','Corner centre'),toolInput('qr-centres',qrState.centres,'type="color"'))+toolField(B('Màu nền','Background colour'),toolInput('qr-background',qrState.background,'type="color"'))+'</div><label class="check-line"><input id="qr-transparent" type="checkbox" '+(qrState.transparent?'checked':'')+'>'+B('Nền trong suốt (PNG/SVG)','Transparent background (PNG/SVG)')+'</label></div></details><details class="tool-details"><summary>'+B('Kiểu dáng & kích thước','Style & size')+'</summary><div class="tool-two tool-fields">'+toolField(B('Kiểu chấm','Dot style'),'<select id="qr-style">'+toolOptions([['rounded',B('Bo nhẹ','Rounded')],['square',B('Vuông','Square')],['dots',B('Tròn','Dots')]],qrState.style)+'</select>')+toolField(B('Kiểu góc','Corner style'),'<select id="qr-corner-style">'+toolOptions([['extra-rounded',B('Bo tròn','Rounded')],['square',B('Vuông','Square')]],qrState.cornerStyle)+'</select>')+toolField(B('Cỡ xuất','Export size'),'<select id="qr-size">'+toolOptions([[512,'512 px'],[1024,'1024 px'],[2048,'2048 px']],qrState.size)+'</select>')+'</div></details><div class="tool-two">'+toolField(B('Tên file','File name'),toolInput('qr-filename',qrState.filename,'placeholder="UEL_'+qrNextNumber()+'" maxlength="90"'))+toolField(B('Định dạng','Format'),'<select id="qr-format">'+toolOptions([['png','PNG'],['svg','SVG'],['jpeg','JPG']],qrState.format)+'</select>')+'</div><p class="tool-caption">'+B('Để trống tên: tự đặt UEL_1, UEL_2… Số lưu trên trình duyệt này.','Leave the name blank for UEL_1, UEL_2… The counter is saved in this browser.')+'</p><button class="btn primary" id="qr-download" '+(qrState.busy?'disabled':'')+'>'+B('Tải mã QR','Download QR')+' ↓</button></div><div class="tool-preview qr-preview"><div style="width:100%"><div id="qr-preview" class="qr-stage" role="img" aria-label="'+B('Mã QR xem trước','QR code preview')+'"></div><p id="qr-status" class="tool-state" role="status"></p><p class="tool-caption">'+B('Giữ lề trống và thử quét bản xuất trước khi in. Mã trắng cần thử trên nền tối thực tế.','Keep the blank margin and test the exported code before printing. Test white codes on their actual dark background.')+'</p></div></div></div>'}
function qrOptions(size,forJpg=false){return {width:size,height:size,type:'canvas',data:qrState.data.trim(),margin:Math.ceil(size*.14),qrOptions:{errorCorrectionLevel:'H'},dotsOptions:{type:qrState.style,color:qrState.dots},cornersSquareOptions:{type:qrState.cornerStyle,color:qrState.corners},cornersDotOptions:{type:qrState.centreStyle,color:qrState.centres},backgroundOptions:{color:qrState.transparent&&!forJpg?'rgba(0,0,0,0)':qrState.background}}}
function validateQr(){const value=qrState.data.trim();if(!value)return B('Dán link hoặc nhập nội dung để tạo mã.','Paste a link or enter text to create a code.');if(new TextEncoder().encode(value).length>1000)return B('Nội dung dài quá; dùng link hoặc văn bản dưới 1.000 byte.','Use a link or text under 1,000 bytes.');return ''}
/* Giữ encoder 1.9.2 đã ghim phiên bản, tự vẽ từng mô-đun để khớp mẫu UEL. */
async function styledQrSvg(size,forJpg=false){const QR=await loadToolLibrary('qr'),encoder=new QR(qrOptions(size,forJpg)),matrix=encoder._qr;if(!matrix||typeof matrix.getModuleCount!=='function')throw Error(B('Không tạo được ma trận QR.','Could not generate the QR matrix.'));const count=matrix.getModuleCount(),margin=Math.ceil(size*.14),pitch=(size-margin*2)/count,gap=pitch*.08,n=value=>Number(value.toFixed(4)),eye=(x,y)=>x<7&&y<7||x>=count-7&&y<7||x<7&&y>=count-7;let body='';if(!qrState.transparent||forJpg)body+='<rect width="'+size+'" height="'+size+'" fill="'+qrState.background+'"/>';for(let y=0;y<count;y++)for(let x=0;x<count;x++){if(eye(x,y)||!matrix.isDark(y,x))continue;const left=margin+x*pitch+gap/2,top=margin+y*pitch+gap/2,width=pitch-gap;if(qrState.style==='dots')body+='<circle cx="'+n(left+width/2)+'" cy="'+n(top+width/2)+'" r="'+n(width/2)+'" fill="'+qrState.dots+'"/>';else body+='<rect x="'+n(left)+'" y="'+n(top)+'" width="'+n(width)+'" height="'+n(width)+'" rx="'+n(qrState.style==='square'?0:width*.24)+'" fill="'+qrState.dots+'"/>'}for(const [x,y]of [[0,0],[count-7,0],[0,count-7]]){const left=margin+x*pitch,top=margin+y*pitch;body+='<rect x="'+n(left+pitch/2)+'" y="'+n(top+pitch/2)+'" width="'+n(pitch*6)+'" height="'+n(pitch*6)+'" rx="'+n(qrState.cornerStyle==='square'?0:pitch*1.5)+'" fill="none" stroke="'+qrState.corners+'" stroke-width="'+n(pitch)+'"/><rect x="'+n(left+pitch*2+gap/2)+'" y="'+n(top+pitch*2+gap/2)+'" width="'+n(pitch*3-gap)+'" height="'+n(pitch*3-gap)+'" rx="'+n(qrState.cornerStyle==='square'?0:pitch*.7)+'" fill="'+qrState.centres+'"/>'}return '<svg xmlns="http://www.w3.org/2000/svg" width="'+size+'" height="'+size+'" viewBox="0 0 '+size+' '+size+'">'+body+'</svg>'}
async function qrImageBlob(size,format){const source=await styledQrSvg(size,format==='jpeg');if(format==='svg')return new Blob([source],{type:'image/svg+xml'});const url=URL.createObjectURL(new Blob([source],{type:'image/svg+xml'}));try{const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error(B('Không tạo được ảnh QR.','Could not create the QR image.')));img.src=url}),canvas=document.createElement('canvas');canvas.width=canvas.height=size;canvas.getContext('2d').drawImage(image,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/'+format,.96));canvas.width=canvas.height=1;if(!blob)throw Error(B('Không tạo được file QR.','Could not create the QR file.'));return blob}finally{URL.revokeObjectURL(url)}}
let qrDebounce;
function scheduleQr(){clearTimeout(qrDebounce);qrDebounce=setTimeout(drawQr,160)}
async function drawQr(){const version=++qrState.version,container=$('#qr-preview');if(!container)return;const invalid=validateQr();if(invalid){container.innerHTML='<div class="tool-placeholder">'+esc(invalid)+'</div>';toolMessage('#qr-status','');return}toolMessage('#qr-status',B('Đang tạo mã…','Generating…'));try{const source=await styledQrSvg(420);if(version!==qrState.version||!$('#qr-preview'))return;$('#qr-preview').innerHTML=source;toolMessage('#qr-status',B('Mã tĩnh: link được lưu trực tiếp trong mã QR.','Static code: the link is stored directly in the QR code.'))}catch(error){if(version===qrState.version)toolMessage('#qr-status',error.message||String(error),true)}}
async function exportQr(){if(qrState.busy)return;const invalid=validateQr();if(invalid){toolMessage('#qr-status',invalid,true);return}qrState.busy=true;const button=$('#qr-download');if(button)button.disabled=true;try{const blob=await qrImageBlob(Number(qrState.size),qrState.format);const save=async()=>{const number=qrNextNumber(),base=safeFileName(qrState.filename.trim().replace(/\.(png|jpe?g|svg)$/i,''),'UEL_'+number);saveToolBlob(blob,base+'.'+(qrState.format==='jpeg'?'jpg':qrState.format));qrState.counter=number;try{localStorage.setItem('meo-qr-download-count',String(number))}catch{}if($('#qr-filename'))$('#qr-filename').placeholder='UEL_'+qrNextNumber()};if(navigator.locks)await navigator.locks.request('meo-qr-download',save);else await save();toast(B('Đã tạo file QR.','QR download ready.'))}catch(error){toolMessage('#qr-status',error.message||String(error),true)}finally{qrState.busy=false;if($('#qr-download'))$('#qr-download').disabled=false}}
document.addEventListener('input',e=>{const fields={'qr-data':'data','qr-dots':'dots','qr-corners':'corners','qr-centres':'centres','qr-background':'background','qr-filename':'filename'};if(fields[e.target.id]){qrState[fields[e.target.id]]=e.target.value;if(e.target.id!=='qr-filename')scheduleQr()}});
document.addEventListener('change',e=>{const fields={'qr-style':'style','qr-corner-style':'cornerStyle','qr-size':'size','qr-format':'format'};if(fields[e.target.id]){qrState[fields[e.target.id]]=e.target.value;if(e.target.id==='qr-format'&&e.target.value==='jpeg'&&qrState.transparent)toolMessage('#qr-status',B('JPG dùng màu nền đặc đã chọn.','JPG uses the selected solid background.'));else scheduleQr()}if(e.target.id==='qr-transparent'){qrState.transparent=e.target.checked;scheduleQr()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-qr-preset]');if(b){const type=b.dataset.qrPreset;Object.assign(qrState,type==='white'?{dots:'#ffffff',corners:'#ffffff',centres:'#ffffff',background:'#10111c',transparent:false}:type==='black'?{dots:'#000000',corners:'#000000',centres:'#000000',background:'#ffffff',transparent:false}:{dots:'#144e8c',corners:'#144e8c',centres:'#f05a22',background:'#ffffff',transparent:true});renderTools()}if(e.target.closest('#qr-download'))exportQr()});

/* TƯƠNG PHẢN: WCAG sRGB, không làm tròn tỷ lệ trước khi xét đạt/chưa đạt. */
const contrastState={foreground:'#144e8c',background:'#ffffff'};
function colourLuminance(hex){const rgb=hex.replace('#','').match(/../g).map(x=>parseInt(x,16)/255).map(c=>c<=.04045?c/12.92:((c+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722}
function contrastRatio(a,b){const x=colourLuminance(a),y=colourLuminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
function contrastPanel(){return '<div class="tool-grid"><div class="tool-fields"><div class="tool-two">'+toolField(B('Màu chữ','Text colour'),toolInput('contrast-foreground',contrastState.foreground,'type="color"'))+toolField(B('Màu nền','Background colour'),toolInput('contrast-background',contrastState.background,'type="color"'))+toolField(B('HEX chữ','Text HEX'),toolInput('contrast-foreground-hex',contrastState.foreground,'maxlength="7" spellcheck="false"'))+toolField(B('HEX nền','Background HEX'),toolInput('contrast-background-hex',contrastState.background,'maxlength="7" spellcheck="false"'))+'</div><div class="row">'+btn(B('Đổi chỗ hai màu','Swap colours'),'id="contrast-swap"')+btn('UEL','id="contrast-uel"')+'</div><div id="contrast-results"></div><p class="tool-caption">'+B('Chữ lớn: từ 18 pt thường hoặc 14 pt đậm. Kết quả đo hai màu đặc, không đại diện mọi vùng của nền ảnh/gradient.','Large text: at least 18 pt regular or 14 pt bold. Results apply to solid colours, not every area of an image or gradient.')+'</p><a class="text-link tool-caption" href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noopener noreferrer">WCAG 2.2 · Contrast ↗</a></div><div class="tool-preview"><div id="contrast-preview" class="contrast-preview"><strong>'+B('Đọc rõ, làm nhanh.','Clear text. Better work.')+'</strong><p>'+B('Trường Đại học Kinh tế – Luật. Đây là đoạn chữ mẫu để xem cách hai màu hiển thị cùng nhau.','University of Economics and Law. Sample text to preview these colours together.')+'</p></div></div></div>'}
function updateContrast(){if(!$('#contrast-results'))return;const {foreground,background}=contrastState,r=contrastRatio(foreground,background),checks=[[B('Chữ thường · AA','Normal text · AA'),4.5],[B('Chữ lớn · AA','Large text · AA'),3],[B('Chữ thường · AAA','Normal text · AAA'),7]];$('#contrast-results').innerHTML='<div class="contrast-score">'+r.toFixed(2)+':1</div><div class="contrast-verdict">'+checks.map(([name,min])=>'<div class="'+(r>=min?'pass':'fail')+'">'+(r>=min?'✓ ':'× ')+esc(name)+' · '+B(r>=min?'Đạt':'Chưa đạt',r>=min?'Pass':'Fail')+'</div>').join('')+'</div>';$('#contrast-preview').style.color=foreground;$('#contrast-preview').style.background=background}
document.addEventListener('input',e=>{if(e.target.id==='contrast-foreground'||e.target.id==='contrast-background'){const key=e.target.id==='contrast-foreground'?'foreground':'background';contrastState[key]=e.target.value;$('#contrast-'+key+'-hex').value=e.target.value;updateContrast()}if(e.target.id==='contrast-foreground-hex'||e.target.id==='contrast-background-hex'){let value=e.target.value.trim();if(!value.startsWith('#'))value='#'+value;if(/^#[0-9a-f]{6}$/i.test(value)){const key=e.target.id.includes('foreground')?'foreground':'background';contrastState[key]=value;$('#contrast-'+key).value=value;updateContrast()}}});
document.addEventListener('click',e=>{if(e.target.closest('#contrast-swap')){[contrastState.foreground,contrastState.background]=[contrastState.background,contrastState.foreground];renderTools()}if(e.target.closest('#contrast-uel')){contrastState.foreground='#144e8c';contrastState.background='#ffffff';renderTools()}});

/* ẢNH HÀNG LOẠT: đọc kích thước trước, giải mã và xử lý từng ảnh. */
const batchState={files:[],outputs:[],busy:false,token:0,mode:'convert',format:'webp',width:'',height:'',quality:.85,rename:false,prefix:'UEL',start:'1',padding:'3',background:'#ffffff',progress:0,message:'',error:false};
function imageLimits(){return matchMedia('(max-width:760px)').matches?{count:8,each:5,total:25,pixels:12000000,maxSide:4096}:{count:20,each:10,total:80,pixels:24000000,maxSide:6000}}
function batchPanel(){
 const rename=currentTool==='rename',compress=currentTool==='compress';
 return uploader('batch-files','image/png,image/jpeg,image/webp','Thả ảnh vào đây',true,'JPG · PNG · WebP · Có thể chọn nhiều ảnh')+
 '<div class="tool-section tool-fields">'+(rename?
 '<div class="tool-two">'+toolField('Tên bắt đầu',toolInput('batch-prefix',batchState.prefix))+toolField('Số bắt đầu',toolInput('batch-start',batchState.start,'type="number" min="1"'))+'</div>'+toolField('Số chữ số','<select id="batch-padding">'+toolOptions([[2,'01'],[3,'001'],[4,'0001']],batchState.padding)+'</select>'):
 compress?toolField('Chất lượng / số màu PNG','<input id="batch-quality" type="range" min="0.1" max="1" step="0.05" value="'+batchState.quality+'">')+'<p class="tool-caption">Giữ kích thước, định dạng và nền trong suốt. PNG giảm số màu để nhẹ hơn; màu có thể thay đổi nhẹ.</p><label class="check-line"><input type="checkbox" id="batch-png-lossless" '+(batchState.pngLossless?'checked':'')+' '+(batchState.busy?'disabled':'')+'>PNG: giữ nguyên màu (mức nén tùy ảnh)</label>':
 toolField('Đổi sang','<select id="batch-format">'+toolOptions([['jpeg','JPG'],['png','PNG'],['webp','WebP']],batchState.format)+'</select>')+'<p class="tool-caption">Giữ kích thước và tên ảnh. JPG dùng nền trắng cho vùng trong suốt.</p>')+
 '</div><div id="batch-list" class="tool-file-list"></div><p id="batch-status" class="tool-state" role="status">'+esc(batchState.message)+'</p><progress id="batch-progress" class="tool-progress" max="100" value="'+batchState.progress+'"></progress><div class="tool-action-bar"><button id="batch-process" class="btn primary" '+(batchState.busy?'disabled':'')+'>Xử lý ảnh</button><button id="batch-download" class="btn" '+(!batchState.outputs.length||batchState.busy?'disabled':'')+'>'+(batchState.outputs.length===1?'Tải ảnh ↓':'Tải tất cả · ZIP ↓')+'</button><button id="batch-clear" class="btn" '+(batchState.busy?'disabled':'')+'>Bỏ tất cả</button><button id="batch-cancel" class="btn" '+(!batchState.busy?'hidden':'')+'>Dừng</button></div>';
}
function batchExt(file){if(batchState.mode==='rename'||batchState.format==='original')return file.name.split('.').pop().toLowerCase();return batchState.format==='jpeg'?'jpg':batchState.format}
function batchOutputName(item,index){const rename=batchState.mode==='rename'||batchState.rename;const prefix=safeFileName(batchState.prefix,'UEL');const number=Number(batchState.start)+index;return rename?prefix+'_'+String(number).padStart(Number(batchState.padding),'0')+'.'+batchExt(item.file):safeFileName(stripExtension(item.file.name),'UEL_'+(index+1))+'.'+batchExt(item.file)}
function batchList(){if(!$('#batch-list'))return;$('#batch-list').innerHTML=batchState.files.map((item,i)=>'<div class="tool-file-row"><div><strong>'+esc(item.file.name)+'</strong><small class="batch-plan">→ '+esc(batchOutputName(item,i))+' · '+mb(item.file.size)+(item.result?' · '+esc(item.result):'')+'</small></div>'+(!batchState.busy&&batchState.outputs.some(o=>o.id===item.id)?'<button class="btn" data-image-download="'+item.id+'">Tải ảnh ↓</button>':'')+'<button data-batch-remove="'+item.id+'" aria-label="'+B('Bỏ ảnh','Remove image')+'" '+(batchState.busy?'disabled':'')+'>×</button></div>').join('');if($('#batch-process'))$('#batch-process').disabled=batchState.busy||!batchState.files.length}
function mountBatch(){bindToolDrop($('#batch-files-drop'),$('#batch-files'),addBatchFiles);batchList();document.querySelectorAll('#batch-files-drop button').forEach(b=>b.disabled=batchState.busy)}
function batchStatus(message,error=false){batchState.message=message;batchState.error=error;toolMessage('#batch-status',message,error)}
function invalidateBatch(){const hadOutput=batchState.outputs.length>0;batchState.outputs=[];batchState.progress=0;batchState.files.forEach(item=>item.result='');if($('#batch-progress'))$('#batch-progress').value=0;if($('#batch-download'))$('#batch-download').disabled=true;if(hadOutput)batchStatus(B('Thông số đã đổi. Bấm Xử lý ảnh để tạo lại.','Settings changed. Process the images again.'));batchList()}
function addBatchFiles(files){if(batchState.busy)return;const l=imageLimits(),all=batchState.files.map(x=>x.file),seen=new Set(all.map(f=>f.name+'|'+f.size+'|'+f.lastModified)),fresh=[];for(const file of files){if(!/^image\/(png|jpeg|webp)$/.test(file.type)){batchStatus(B('Chỉ nhận JPG, PNG và WebP.','Only JPG, PNG and WebP are supported.'),true);return}if(file.size>l.each*1048576){batchStatus(B('Mỗi ảnh tối đa '+l.each+' MB.','Each image must be under '+l.each+' MB.'),true);return}const key=file.name+'|'+file.size+'|'+file.lastModified;if(!seen.has(key)){seen.add(key);fresh.push(file)}}if(all.length+fresh.length>l.count||[...all,...fresh].reduce((n,f)=>n+f.size,0)>l.total*1048576){batchStatus(B('Vượt giới hạn '+l.count+' ảnh hoặc tổng '+l.total+' MB.','Limit exceeded: '+l.count+' images or '+l.total+' MB total.'),true);return}batchState.files.push(...fresh.map(file=>({id:crypto.randomUUID?crypto.randomUUID():String(Math.random()),file,result:''})));invalidateBatch();batchStatus(B('Đã chọn '+batchState.files.length+' ảnh.','Selected '+batchState.files.length+' images.'));batchList()}
async function rasterSize(file){const a=new Uint8Array(await file.slice(0,262144).arrayBuffer()),d=new DataView(a.buffer);if(a.length>=24&&a[0]===137&&a[1]===80&&a[2]===78&&a[3]===71)return {width:d.getUint32(16),height:d.getUint32(20)};if(a[0]===255&&a[1]===216){let p=2;while(p+8<a.length){if(a[p]!==255){p++;continue}const marker=a[p+1];p+=2;if(marker===216||marker===217)continue;const len=d.getUint16(p);if(len<2)break;if([192,193,194,195,197,198,199,201,202,203,205,206,207].includes(marker))return {height:d.getUint16(p+3),width:d.getUint16(p+5)};p+=len}}if(a.length>=30&&String.fromCharCode(...a.slice(0,4))==='RIFF'&&String.fromCharCode(...a.slice(8,12))==='WEBP'){const kind=String.fromCharCode(...a.slice(12,16));if(kind==='VP8X')return {width:1+a[24]+(a[25]<<8)+(a[26]<<16),height:1+a[27]+(a[28]<<8)+(a[29]<<16)};if(kind==='VP8 ')return {width:d.getUint16(26,true)&16383,height:d.getUint16(28,true)&16383};if(kind==='VP8L'){const bits=d.getUint32(21,true);return {width:1+(bits&16383),height:1+((bits>>>14)&16383)}}}throw Error(B('Không đọc được kích thước ảnh.','Could not read the image dimensions.'))}
async function bitmapFor(file){if(window.createImageBitmap)return createImageBitmap(file);const url=URL.createObjectURL(file);return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{URL.revokeObjectURL(url);resolve(image)};image.onerror=()=>{URL.revokeObjectURL(url);reject(Error(B('Không giải mã được ảnh.','Could not decode the image.')))};image.src=url})}
function validateBatchSettings(){const l=imageLimits();if(batchState.files.length>l.count||batchState.files.some(item=>item.file.size>l.each*1048576)||batchState.files.reduce((n,item)=>n+item.file.size,0)>l.total*1048576)return B('Danh sách vượt giới hạn thiết bị hiện tại. Bỏ bớt ảnh hoặc dùng máy tính.','The list exceeds the current device limits. Remove images or use a desktop.');if((batchState.mode==='rename'||batchState.rename)&&(!Number.isInteger(Number(batchState.start))||Number(batchState.start)<1||Number(batchState.start)>999999))return B('Số bắt đầu phải từ 1 đến 999999.','The starting number must be between 1 and 999999.');if(batchState.mode!=='rename')for(const value of [batchState.width,batchState.height])if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<1||Number(value)>l.maxSide))return B('Kích thước phải từ 1 đến '+l.maxSide+' px.','Dimensions must be between 1 and '+l.maxSide+' px.');return ''}
async function processBatch(){if(batchState.busy||!batchState.files.length)return;const invalid=validateBatchSettings();if(invalid){batchStatus(invalid,true);return}const token=++batchState.token,l=imageLimits();batchState.busy=true;batchState.progress=0;batchState.outputs=[];batchState.files.forEach(f=>f.result='');renderTools();let failures=0,total=0;const usedNames=new Set();for(let i=0;i<batchState.files.length;i++){if(token!==batchState.token)break;const item=batchState.files[i];try{let blob=item.file;if(batchState.mode!=='rename'){const dimensions=await rasterSize(item.file);if(dimensions.width<1||dimensions.height<1||dimensions.width*dimensions.height>l.pixels)throw Error(B('Ảnh vượt '+l.pixels/1000000+' triệu pixel.','Image exceeds '+l.pixels/1000000+' megapixels.'));const bitmap=await bitmapFor(item.file);try{const scale=Math.min(1,(Number(batchState.width)||bitmap.width)/bitmap.width,(Number(batchState.height)||bitmap.height)/bitmap.height,l.maxSide/Math.max(bitmap.width,bitmap.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=c.getContext('2d');const mime=batchState.format==='original'?item.file.type:'image/'+batchState.format;if(mime==='image/jpeg'){ctx.fillStyle=batchState.background;ctx.fillRect(0,0,c.width,c.height)}ctx.drawImage(bitmap,0,0,c.width,c.height);blob=currentTool==='compress'&&mime==='image/png'?await compressPng(c,batchState.pngLossless?0:Math.round(32+224*Number(batchState.quality))):await new Promise(resolve=>c.toBlob(resolve,mime,batchState.quality));if(currentTool==='compress'&&blob&&blob.size>=item.file.size)blob=item.file;if(!blob||blob.type!==mime)throw Error(B('Trình duyệt chưa hỗ trợ định dạng này. Chọn PNG/JPG.','This format is not supported here. Choose PNG/JPG.'));item.result=c.width+' × '+c.height+' px · '+mb(blob.size)+(currentTool==='compress'?(blob.size<item.file.size?' · Giảm '+Math.round((1-blob.size/item.file.size)*100)+'%':' · Đã tối ưu, giữ file gốc'):'');c.width=c.height=1}finally{bitmap.close?.()}}else item.result=B('Giữ nguyên nội dung · ','Original content · ')+mb(blob.size);if(token!==batchState.token)break;if(total+blob.size>l.total*1048576)throw Error(B('Tổng file xuất vượt '+l.total+' MB; giảm kích thước/chất lượng.','Output exceeds '+l.total+' MB; reduce dimensions or quality.'));let name=batchOutputName(item,i),base=stripExtension(name),ext=name.split('.').pop(),suffix=2;while(usedNames.has(name.toLowerCase()))name=base+'_'+suffix+++'.'+ext;usedNames.add(name.toLowerCase());batchState.outputs.push({id:item.id,mime:blob.type,name,bytes:new Uint8Array(await blob.arrayBuffer())});total+=blob.size}catch(error){failures++;item.result=B('Lỗi: ','Error: ')+(error.message||String(error))}batchState.progress=Math.round((i+1)/batchState.files.length*100);if($('#batch-progress'))$('#batch-progress').value=batchState.progress;batchStatus(B('Đang xử lý ','Processing ')+(i+1)+'/'+batchState.files.length);batchList();await nextPaint()}
if(token!==batchState.token){batchState.outputs=[];batchStatus(B('Đã hủy. Có thể chỉnh thông số và chạy lại.','Cancelled. Adjust the settings and try again.'))}else batchStatus(B('Xong '+batchState.outputs.length+'/'+batchState.files.length+' ảnh.','Processed '+batchState.outputs.length+'/'+batchState.files.length+' images.')+(failures?B(' Có '+failures+' ảnh lỗi; xem danh sách.',' '+failures+' failed; see the list.'):'')+' '+mb(total),!!failures);batchState.busy=false;if(toolTab==='images'&&!!currentTool)renderTools()}
async function downloadBatch(){if(batchState.busy||!batchState.outputs.length)return;const button=$('#batch-download');if(button)button.disabled=true;try{if(batchState.outputs.length===1){saveImageOutput(batchState.outputs[0]);return}const zip=await loadToolLibrary('zip'),files=Object.fromEntries(batchState.outputs.map(r=>[r.name,r.bytes]));await nextPaint();saveToolBlob(new Blob([zip.zipSync(files,{level:0})],{type:'application/zip'}),'UEL_Anh.zip');toast(B('Đã tạo ZIP.','ZIP download ready.'))}catch(error){batchStatus(error.message,true)}finally{if($('#batch-download'))$('#batch-download').disabled=false}}
document.addEventListener('input',e=>{const map={'batch-width':'width','batch-height':'height','batch-prefix':'prefix','batch-start':'start','batch-background':'background','batch-quality':'quality'};if(map[e.target.id]&&!batchState.busy){batchState[map[e.target.id]]=e.target.value;if(e.target.id==='batch-quality')$('#batch-quality').setAttribute('aria-valuetext',Math.round(Number(e.target.value)*100)+'%');invalidateBatch()}});
document.addEventListener('change',e=>{if(batchState.busy)return;if(e.target.id==='batch-mode'){batchState.mode=e.target.value;invalidateBatch();renderTools()}if(e.target.id==='batch-format'){batchState.format=e.target.value;invalidateBatch();renderTools()}if(e.target.id==='batch-rename'){batchState.rename=e.target.checked;invalidateBatch()}if(e.target.id==='batch-padding'){batchState.padding=e.target.value;invalidateBatch()}});
document.addEventListener('click',e=>{if(e.target.closest('#batch-process'))processBatch();if(e.target.closest('#batch-download'))downloadBatch();if(e.target.closest('#batch-cancel'))batchState.token++;if(e.target.closest('#batch-clear')&&!batchState.busy){batchState.files=[];batchState.outputs=[];batchState.progress=0;batchState.message='';renderTools()}const remove=e.target.closest('[data-batch-remove]');if(remove&&!batchState.busy){batchState.files=batchState.files.filter(f=>f.id!==remove.dataset.batchRemove);invalidateBatch();batchStatus('')}});

/* PDF: chỉ chỉnh trang, giữ nội dung gốc. Thumbnail được vẽ khi đi vào vùng nhìn. */
const pdfState={documents:[],pages:[],busy:false,token:0,page:0,filename:'UEL_Tai-lieu',message:'',error:false,previewWarning:false,errors:[]};
let pdfSerial=0,pdfObserver=null,pdfModulePromise=null,pdfSharedWorker=null;
const pdfRenderTasks=new Set(),pdfThumbs=new Map();
function pdfLimits(){return matchMedia('(max-width:760px)').matches?{files:5,bytes:20*1048576,pages:50,output:40*1048576}:{files:10,bytes:50*1048576,pages:100,output:100*1048576}}
function pdfPanel(){const l=pdfLimits();return uploader('pdf-files','.pdf,application/pdf',B('Kéo một hoặc nhiều PDF vào đây','Drop one or more PDF files here'),true,B('Tối đa '+l.files+' file · '+l.bytes/1048576+' MB · '+l.pages+' trang','Up to '+l.files+' files · '+l.bytes/1048576+' MB · '+l.pages+' pages'))+'<p class="tool-caption" style="margin-top:12px">'+B('Chọn trang để xuất. Kéo thả hoặc dùng ↑ ↓ để đổi thứ tự. File có mật khẩu chưa được hỗ trợ.','Select pages to export. Drag or use ↑ ↓ to reorder. Password-protected files are not supported.')+'</p><div class="tool-action-bar tool-section"><button class="btn" id="pdf-all" '+(pdfState.busy?'disabled':'')+'>'+B('Chọn tất cả','Select all')+'</button><button class="btn" id="pdf-none" '+(pdfState.busy?'disabled':'')+'>'+B('Bỏ chọn','Deselect all')+'</button><button class="btn" id="pdf-restore" '+(pdfState.busy?'disabled':'')+'>'+B('Khôi phục tất cả','Restore all')+'</button><button class="btn" id="pdf-clear" '+(pdfState.busy?'disabled':'')+'>'+B('Xóa danh sách','Clear list')+'</button></div><p class="tool-state '+(pdfState.error?'error':'')+'" id="pdf-status" role="status">'+esc(pdfState.message)+'</p><div id="pdf-summary" class="tool-caption"></div><div id="pdf-pages" class="pdf-pages"></div><div id="pdf-pagination" class="pdf-pagination"></div><div class="tool-section tool-fields"><div class="tool-two">'+toolField(B('Tên file xuất','Output file name'),toolInput('pdf-filename',pdfState.filename,'maxlength="90"'))+'<div class="tool-action-bar" style="align-self:end"><button class="btn primary" id="pdf-merge" '+(pdfState.busy||!pdfState.pages.some(p=>p.selected)?'disabled':'')+'>'+B('Gộp / Xuất PDF','Merge / Export PDF')+' ↓</button><button class="btn" id="pdf-split" '+(pdfState.busy||!pdfState.pages.some(p=>p.selected)?'disabled':'')+'>'+B('Tách trang · ZIP','Split pages · ZIP')+' ↓</button></div></div></div>'}
function pdfStatus(message,error=false){pdfState.message=message;pdfState.error=error;toolMessage('#pdf-status',message,error)}
async function pdfRenderer(){if(!pdfModulePromise)pdfModulePromise=import(new URL('assets/pdf.min.mjs',document.baseURI).href).then(module=>{module.GlobalWorkerOptions.workerSrc=new URL('assets/pdf.worker.min.mjs',document.baseURI).href;return module}).catch(error=>{pdfModulePromise=null;throw error});return pdfModulePromise}
function stopPdfThumbnails(){pdfObserver?.disconnect();for(const task of pdfRenderTasks)task.cancel();pdfRenderTasks.clear()}
function pdfDocument(id){return pdfState.documents.find(d=>d.id===id)}
function pdfVisibleRows(){return pdfState.pages.slice(pdfState.page*12,pdfState.page*12+12)}
function renderPdfPages(){if(!$('#pdf-pages'))return;stopPdfThumbnails();const maxPage=Math.max(0,Math.ceil(pdfState.pages.length/12)-1);pdfState.page=Math.min(pdfState.page,maxPage);const selected=pdfState.pages.filter(p=>p.selected).length;$('#pdf-summary').textContent=pdfState.documents.length+' '+B('file','files')+' · '+pdfState.pages.length+' '+B('trang','pages')+' · '+selected+' '+B('đã chọn','selected');$('#pdf-pages').innerHTML=pdfVisibleRows().map(row=>{const index=pdfState.pages.indexOf(row),doc=pdfDocument(row.document);return '<article class="pdf-page" data-pdf-id="'+row.id+'" draggable="'+(!pdfState.busy)+'"><div class="pdf-thumb"><canvas data-pdf-thumb="'+row.id+'" aria-label="'+B('Xem trước trang ','Preview page ')+(index+1)+'"></canvas></div><div class="pdf-page-meta"><label><input type="checkbox" data-pdf-select="'+row.id+'" '+(row.selected?'checked':'')+' '+(pdfState.busy?'disabled':'')+'>'+B('Trang ','Page ')+(index+1)+'</label><small>'+esc(doc.name)+' · '+B('trang gốc ','source page ')+(row.source+1)+'</small><div class="pdf-page-actions"><button data-pdf-move="'+row.id+'" data-direction="-1" aria-label="'+B('Chuyển trang lên','Move page up')+'" '+(pdfState.busy||index===0?'disabled':'')+'>↑</button><button data-pdf-move="'+row.id+'" data-direction="1" aria-label="'+B('Chuyển trang xuống','Move page down')+'" '+(pdfState.busy||index===pdfState.pages.length-1?'disabled':'')+'>↓</button><button data-pdf-rotate="'+row.id+'" aria-label="'+B('Xoay 90 độ','Rotate 90 degrees')+'" '+(pdfState.busy?'disabled':'')+'>↻</button><button data-pdf-delete="'+row.id+'" aria-label="'+B('Bỏ trang','Remove page')+'" '+(pdfState.busy?'disabled':'')+'>×</button></div></div></article>'}).join('');$('#pdf-pagination').innerHTML=pdfState.pages.length?'<button class="btn" id="pdf-prev" '+(pdfState.page===0||pdfState.busy?'disabled':'')+'>←</button><span>'+(pdfState.page+1)+' / '+(maxPage+1)+'</span><button class="btn" id="pdf-next" '+(pdfState.page===maxPage||pdfState.busy?'disabled':'')+'>→</button>':'';$('#pdf-merge').disabled=$('#pdf-split').disabled=pdfState.busy||!selected;if('IntersectionObserver'in window){pdfObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){pdfObserver.unobserve(entry.target);renderPdfThumbnail(entry.target)}}),{root:$('#quick-tools'),rootMargin:'80px'});document.querySelectorAll('[data-pdf-thumb]').forEach(c=>pdfObserver.observe(c))}else document.querySelectorAll('[data-pdf-thumb]').forEach(renderPdfThumbnail)}
async function renderPdfThumbnail(canvas){const row=pdfState.pages.find(r=>r.id===canvas.dataset.pdfThumb);if(!row)return;const doc=pdfDocument(row.document),key=row.id+':'+row.rotation;try{if(pdfThumbs.has(key)){const image=pdfThumbs.get(key);canvas.width=image.width;canvas.height=image.height;canvas.getContext('2d').drawImage(image,0,0);return}if(!doc.rendering)doc.rendering=pdfRenderer().then(module=>{if(!pdfState.documents.includes(doc))throw Error('Preview cancelled');pdfSharedWorker??=new module.PDFWorker({name:'UEL-PDF-preview'});return module.getDocument({data:doc.bytes.slice(),worker:pdfSharedWorker,isEvalSupported:false,useSystemFonts:true,useWorkerFetch:false}).promise});const renderer=await doc.rendering,page=await renderer.getPage(row.source+1);if(!canvas.isConnected)return;const basic=page.getViewport({scale:1,rotation:(page.rotate+row.rotation)%360}),viewport=page.getViewport({scale:Math.min(180/basic.width,240/basic.height),rotation:(page.rotate+row.rotation)%360});canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);const task=page.render({canvasContext:canvas.getContext('2d'),viewport});pdfRenderTasks.add(task);try{await task.promise}finally{pdfRenderTasks.delete(task)}if(!canvas.isConnected)return;const cache=document.createElement('canvas');cache.width=canvas.width;cache.height=canvas.height;cache.getContext('2d').drawImage(canvas,0,0);pdfThumbs.set(key,cache);if(pdfThumbs.size>24){const first=pdfThumbs.keys().next().value;const old=pdfThumbs.get(first);old.width=old.height=1;pdfThumbs.delete(first)}}catch(error){if(error?.name==='RenderingCancelledException'||!canvas.isConnected)return;if(canvas.isConnected){canvas.width=180;canvas.height=240;const ctx=canvas.getContext('2d');ctx.fillStyle='#eeeef4';ctx.fillRect(0,0,180,240);ctx.fillStyle='#666';ctx.textAlign='center';ctx.font='14px sans-serif';ctx.fillText('PDF · '+(row.source+1),90,120)}if(!pdfState.previewWarning){pdfState.previewWarning=true;pdfStatus(B('Chưa tạo được hình xem trước. Vẫn có thể chọn, sắp xếp và xuất trang.','Page previews are unavailable. You can still select, reorder and export pages.'))}}}
function mountPdf(){bindToolDrop($('#pdf-files-drop'),$('#pdf-files'),addPdfFiles);document.querySelectorAll('#pdf-files-drop button').forEach(b=>b.disabled=pdfState.busy);renderPdfPages()}
async function addPdfFiles(files){if(pdfState.busy||!files.length)return;const l=pdfLimits(),existing=new Set(pdfState.documents.map(d=>d.key)),incoming=files.filter(f=>!existing.has(f.name+'|'+f.size+'|'+f.lastModified));if(incoming.some(f=>!f.name.toLowerCase().endsWith('.pdf'))){pdfStatus(B('Chọn file có định dạng PDF.','Choose PDF files.'),true);return}if(pdfState.documents.length+incoming.length>l.files||pdfState.documents.reduce((n,d)=>n+d.bytes.length,0)+incoming.reduce((n,f)=>n+f.size,0)>l.bytes){pdfStatus(B('Vượt giới hạn '+l.files+' file hoặc '+l.bytes/1048576+' MB.','Limit exceeded: '+l.files+' files or '+l.bytes/1048576+' MB.'),true);return}const token=++pdfState.token;pdfState.busy=true;pdfState.errors=[];renderTools();let failed=0;try{const lib=await loadToolLibrary('pdf');for(const file of incoming){if(token!==pdfState.token)break;try{pdfStatus(B('Đang đọc ','Reading ')+file.name);const bytes=new Uint8Array(await file.arrayBuffer());if(String.fromCharCode(...bytes.slice(0,5))!=='%PDF-')throw Error(B('File không phải PDF hợp lệ.','This is not a valid PDF.'));const document=await lib.PDFDocument.load(bytes,{updateMetadata:false});const pages=document.getPageCount();if(pdfState.documents.reduce((n,d)=>n+d.pageCount,0)+pages>l.pages)throw Error(B('Tổng số trang vượt '+l.pages+'.','The page count exceeds '+l.pages+'.'));if(token!==pdfState.token)break;const id='pdf-'+(++pdfSerial);pdfState.documents.push({id,name:file.name,key:file.name+'|'+file.size+'|'+file.lastModified,bytes,document,pageCount:pages,rendering:null});for(let i=0;i<pages;i++)pdfState.pages.push({id:id+'-'+i,document:id,source:i,rotation:0,selected:true})}catch(error){failed++;const raw=error.message||String(error),detail=/encrypt|password/i.test(raw)?B('Chưa hỗ trợ PDF có mật khẩu.','Password-protected PDFs are not supported.'):/trang vượt|page count exceeds/i.test(raw)?raw:B('Không đọc được PDF này.','Could not read this PDF.');pdfState.errors.push(file.name+': '+detail);pdfStatus(pdfState.errors.join(' · '),true)}await nextPaint()}if(token===pdfState.token){const message=B('Đã đọc '+pdfState.documents.length+' file, '+pdfState.pages.length+' trang.','Loaded '+pdfState.documents.length+' files, '+pdfState.pages.length+' pages.');pdfStatus(message+(failed?' '+pdfState.errors.join(' · '):''),!!failed)}}catch(error){pdfStatus(error.message||String(error),true)}finally{pdfState.busy=false;if(toolTab==='pdf'&&!!currentTool)renderTools()}}
function originalPdfRows(){return pdfState.documents.flatMap(doc=>Array.from({length:doc.pageCount},(_,i)=>({id:doc.id+'-'+i,document:doc.id,source:i,rotation:0,selected:true})))}
function clearPdf(){if(pdfState.busy)return;stopPdfThumbnails();const oldWorker=pdfSharedWorker;pdfSharedWorker=null;Promise.all(pdfState.documents.filter(doc=>doc.rendering).map(doc=>doc.rendering.then(renderer=>renderer.destroy()).catch(()=>{}))).finally(()=>oldWorker?.destroy());for(const canvas of pdfThumbs.values())canvas.width=canvas.height=1;pdfThumbs.clear();pdfState.documents=[];pdfState.pages=[];pdfState.page=0;pdfState.message='';pdfState.previewWarning=false;renderTools()}
async function exportPdf(split){if(pdfState.busy)return;const selected=pdfState.pages.filter(p=>p.selected);if(!selected.length){pdfStatus(B('Chọn ít nhất một trang.','Select at least one page.'),true);return}const l=pdfLimits();if(pdfState.documents.length>l.files||pdfState.documents.reduce((n,d)=>n+d.bytes.length,0)>l.bytes||pdfState.documents.reduce((n,d)=>n+d.pageCount,0)>l.pages){pdfStatus(B('Danh sách vượt giới hạn thiết bị hiện tại. Xóa bớt file hoặc dùng máy tính.','This list exceeds the current device limits. Remove files or use a desktop.'),true);return}const token=++pdfState.token;pdfState.busy=true;renderTools();try{const lib=await loadToolLibrary('pdf'),base=safeFileName(stripExtension(pdfState.filename),'UEL_Tai-lieu');if(split){const zip=await loadToolLibrary('zip'),entries={};let total=0;for(let i=0;i<selected.length;i++){if(token!==pdfState.token)return;const row=selected[i],source=pdfDocument(row.document),output=await lib.PDFDocument.create(),[copy]=await output.copyPages(source.document,[row.source]);copy.setRotation(lib.degrees((copy.getRotation().angle+row.rotation)%360));output.addPage(copy);const bytes=await output.save();total+=bytes.length;if(total>l.output)throw Error(B('File tách vượt giới hạn dung lượng; chọn ít trang hơn.','The split output is too large; select fewer pages.'));entries[base+'_'+String(i+1).padStart(3,'0')+'.pdf']=bytes;pdfStatus(B('Đang tách trang ','Splitting page ')+(i+1)+'/'+selected.length);await nextPaint()}if(token!==pdfState.token)return;saveToolBlob(new Blob([zip.zipSync(entries,{level:0})],{type:'application/zip'}),base+'_trang.zip')}else{const output=await lib.PDFDocument.create(),copied=new Map();for(const source of pdfState.documents){if(token!==pdfState.token)return;const rows=selected.filter(row=>row.document===source.id);if(!rows.length)continue;const pages=await output.copyPages(source.document,rows.map(row=>row.source));rows.forEach((row,i)=>copied.set(row.id,pages[i]))}for(let i=0;i<selected.length;i++){if(token!==pdfState.token)return;const row=selected[i],copy=copied.get(row.id);copy.setRotation(lib.degrees((copy.getRotation().angle+row.rotation)%360));output.addPage(copy);pdfStatus(B('Đang ghép trang ','Merging page ')+(i+1)+'/'+selected.length);await nextPaint()}const bytes=await output.save();if(bytes.length>l.output)throw Error(B('PDF xuất quá lớn; chọn ít trang hơn.','The output PDF is too large; select fewer pages.'));if(token!==pdfState.token)return;saveToolBlob(new Blob([bytes],{type:'application/pdf'}),base+'.pdf')}pdfStatus(B('Đã tạo file tải xuống.','Download ready.'))}catch(error){pdfStatus(error.message||String(error),true)}finally{pdfState.busy=false;if(toolTab==='pdf'&&!!currentTool)renderTools()}}
document.addEventListener('change',e=>{const id=e.target.dataset?.pdfSelect;if(id&&!pdfState.busy){const row=pdfState.pages.find(p=>p.id===id);if(row)row.selected=e.target.checked;const selected=pdfState.pages.filter(p=>p.selected).length;if($('#pdf-summary'))$('#pdf-summary').textContent=pdfState.pages.length+' '+B('trang','pages')+' · '+selected+' '+B('đã chọn','selected');$('#pdf-merge').disabled=$('#pdf-split').disabled=!selected}});
document.addEventListener('input',e=>{if(e.target.id==='pdf-filename')pdfState.filename=e.target.value});
document.addEventListener('click',e=>{if(e.target.closest('#pdf-merge'))exportPdf(false);if(e.target.closest('#pdf-split'))exportPdf(true);if(pdfState.busy)return;let changed=false;if(e.target.closest('#pdf-all')){pdfState.pages.forEach(p=>p.selected=true);changed=true}if(e.target.closest('#pdf-none')){pdfState.pages.forEach(p=>p.selected=false);changed=true}if(e.target.closest('#pdf-restore')){pdfState.pages=originalPdfRows();pdfState.page=0;changed=true}if(e.target.closest('#pdf-clear')){clearPdf();return}if(e.target.closest('#pdf-prev')){pdfState.page--;changed=true}if(e.target.closest('#pdf-next')){pdfState.page++;changed=true}const rotate=e.target.closest('[data-pdf-rotate]');if(rotate){const row=pdfState.pages.find(p=>p.id===rotate.dataset.pdfRotate);if(row)row.rotation=(row.rotation+90)%360;changed=true}const remove=e.target.closest('[data-pdf-delete]');if(remove){pdfState.pages=pdfState.pages.filter(p=>p.id!==remove.dataset.pdfDelete);changed=true}const move=e.target.closest('[data-pdf-move]');if(move){const index=pdfState.pages.findIndex(p=>p.id===move.dataset.pdfMove),next=index+Number(move.dataset.direction);if(index>=0&&next>=0&&next<pdfState.pages.length){[pdfState.pages[index],pdfState.pages[next]]=[pdfState.pages[next],pdfState.pages[index]];pdfState.page=Math.floor(next/12);changed=true}}if(changed)renderPdfPages()});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-pdf-id]');if(!card||pdfState.busy)return;e.dataTransfer.setData('text/plain',card.dataset.pdfId);e.dataTransfer.effectAllowed='move'});document.addEventListener('dragover',e=>{const card=e.target.closest('[data-pdf-id]');if(card&&!pdfState.busy){e.preventDefault();e.dataTransfer.dropEffect='move';card.classList.add('dragover')}});document.addEventListener('dragleave',e=>e.target.closest('[data-pdf-id]')?.classList.remove('dragover'));document.addEventListener('drop',e=>{const card=e.target.closest('[data-pdf-id]');if(!card||pdfState.busy)return;e.preventDefault();card.classList.remove('dragover');const id=e.dataTransfer.getData('text/plain'),index=pdfState.pages.findIndex(p=>p.id===id);if(index<0||id===card.dataset.pdfId)return;const [row]=pdfState.pages.splice(index,1),target=pdfState.pages.findIndex(p=>p.id===card.dataset.pdfId);pdfState.pages.splice(target,0,row);renderPdfPages()});
let pngJob=null;
function compressPng(canvas,colours){return new Promise((resolve,reject)=>{const rgba=canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data;const worker=new Worker('assets/png-compress-worker.js');pngJob={worker,reject};const finish=()=>{worker.terminate();if(pngJob?.worker===worker)pngJob=null};worker.onmessage=e=>{finish();if(e.data.error)reject(Error(e.data.error));else resolve(new Blob([e.data.result],{type:'image/png'}))};worker.onerror=()=>{finish();reject(Error('Không nén được PNG. Thử lại hoặc chọn giữ nguyên màu.'))};worker.postMessage({rgba:rgba.buffer,width:canvas.width,height:canvas.height,colours},[rgba.buffer])})}
function saveImageOutput(output){saveToolBlob(new Blob([output.bytes],{type:output.mime||'application/octet-stream'}),output.name)}
document.addEventListener('click',e=>{const download=e.target.closest('[data-image-download]');if(download&&!batchState.busy){const output=batchState.outputs.find(o=>o.id===download.dataset.imageDownload);if(output)saveImageOutput(output)}if(e.target.closest('#batch-cancel')&&pngJob){const job=pngJob;pngJob=null;job.worker.terminate();job.reject(Error('Đã dừng xử lý.'))}});
document.addEventListener('change',e=>{if(e.target.id==='batch-png-lossless'&&!batchState.busy){batchState.pngLossless=e.target.checked;invalidateBatch()}});
